void kmp_prefix_table_1(const char* pattern, int* pi, int m) {
    pi[0] = 0;
    int k = 0;
    for (int q = 1; q < m; q++) {
        while (k > 0 && pattern[k] != pattern[q]) k = pi[k - 1];
        if (pattern[k] == pattern[q]) k++;
        pi[q] = k;
    }
}

int binary_lifting_lca_1(int u, int v, int up[][20], int* depth) {
    if (depth[u] < depth[v]) { int t = u; u = v; v = t; }
    for (int k = 19; k >= 0; k--) {
        if (depth[u] - (1 << k) >= depth[v]) u = up[u][k];
    }
    if (u == v) return u;
    for (int k = 19; k >= 0; k--) {
        if (up[u][k] != up[v][k]) { u = up[u][k]; v = up[v][k]; }
    }
    return up[u][0];
}

